from (values
('mcq', 1, 'ما تعبير ثابت حاصل الذائبية لفوسفات الفضة Ag₃PO₄ القليلة الذوبان؟', null, null, '["Ksp = [Ag⁺][PO₄³⁻]","Ksp = [Ag⁺]³[PO₄³⁻]","Ksp = [3Ag⁺][PO₄³⁻]","Ksp = [Ag⁺]³[PO₄³⁻] / [Ag₃PO₄]"]'::jsonb, 'تطبيق', 'كتابة تعبير Ksp', 'سهل', 'الكتاب ص 100–101 — كتابة تعبير ثابت حاصل الذائبية'),
('mcq', 2, 'يمثل الشكل الآتي محلولًا مشبعًا من هيدروكسيد الماغنسيوم Mg(OH)₂ فوق مادته الصلبة. أيّ مما يأتي يمثل تعبير ثابت حاصل الذائبية لهذا الاتزان؟', null, '[{"src":"qimg/chem22/c3-l3b-sat-mgoh2.svg","alt":"كأس فيها محلول مشبع، وفي قاعها طبقة من مادة صلبة غير مذابة مكتوب عليها Mg(OH)₂(s). في المحلول فوق المادة الصلبة 4 أيونات Mg²⁺ (دوائر خضراء) و8 أيونات OH⁻ (دوائر زرقاء)، أي إن عدد أيونات OH⁻ ضعف عدد أيونات Mg²⁺. وبجانب الكأس مفتاح: دائرة خضراء = أيون Mg²⁺، دائرة زرقاء = أيون OH⁻، مستطيل أصفر = مادة صلبة غير مذابة."}]'::jsonb, '["Ksp = [Mg²⁺][OH⁻]","Ksp = [Mg²⁺]²[OH⁻]","Ksp = [Mg²⁺][OH⁻]² / [Mg(OH)₂]","Ksp = [Mg²⁺][OH⁻]²"]'::jsonb, 'تطبيق', 'كتابة تعبير Ksp من شكل', 'سهل', 'الكتاب ص 101 — تعبير Ksp لـ Mg(OH)₂'),
('mcq', 3, 'يمثل الشكل الآتي محلولًا مشبعًا لمركب أيوني قليل الذوبان يتكون من الأيونين A³⁺ وB⁻ فوق مادته الصلبة. ما تعبير ثابت حاصل الذائبية لهذا المركب؟', null, '[{"src":"qimg/chem22/c3-l3b-sat-unknown.svg","alt":"كأس فيها محلول مشبع، وفي قاعها طبقة من مادة صلبة غير مذابة. في المحلول 3 أيونات A³⁺ (دوائر حمراء) و9 أيونات B⁻ (دوائر زرقاء)، أي إن عدد أيونات B⁻ ثلاثة أمثال عدد أيونات A³⁺. وبجانب الكأس مفتاح: دائرة حمراء = أيون A³⁺، دائرة زرقاء = أيون B⁻، مستطيل أصفر = مادة صلبة غير مذابة."}]'::jsonb, '["Ksp = [A³⁺][B⁻]³","Ksp = [A³⁺][B⁻]","Ksp = [A³⁺]³[B⁻]","Ksp = [A³⁺][B⁻]³ / [AB₃]"]'::jsonb, 'تحليل', 'استنتاج تعبير Ksp من نموذج جسيمات', 'صعب', 'الكتاب ص 100–101 — كتابة تعبير ثابت حاصل الذائبية'),
('mcq', 4, 'ما معادلة اتزان الذوبان الصحيحة لفوسفات الكالسيوم Ca₃(PO₄)₂ في الماء؟', null, null, '["Ca₃(PO₄)₂(s) ⇌ 2Ca³⁺(aq) + 3PO₄²⁻(aq)","Ca₃(PO₄)₂(s) ⇌ Ca²⁺(aq) + PO₄³⁻(aq)","Ca₃(PO₄)₂(s) ⇌ 3Ca²⁺(aq) + 2PO₄³⁻(aq)","Ca₃(PO₄)₂(s) ⇌ 3Ca²⁺(aq) + 2P⁵⁺(aq) + 8O²⁻(aq)"]'::jsonb, 'تطبيق', 'كتابة معادلة اتزان الذوبان', 'متوسط', 'الكتاب ص 101 — الجدول 3-3 (الفوسفات)'),
('mcq', 5, 'لماذا لا يظهر BaSO₄(s) في تعبير ثابت حاصل الذائبية Ksp = [Ba²⁺][SO₄²⁻]؟', null, null, '["لأن BaSO₄ لا يذوب في الماء مطلقًا","لأن كمية المادة الصلبة صغيرة جدًّا مقارنة بالأيونات","لأن تركيز المادة الصلبة النقية ثابت عند درجة حرارة معينة","لأن المادة الصلبة تُستهلك كلها عند الوصول إلى الاتزان"]'::jsonb, 'فهم', 'تفسير قاعدة', 'متوسط', 'الكتاب ص 100–101 — كتابة تعبير ثابت حاصل الذائبية'),
('mcq', 6, 'تعبير ثابت حاصل الذائبية لمركب قليل الذوبان هو: Ksp = [Pb²⁺]³[AsO₄³⁻]². ما صيغة هذا المركب؟', null, null, '["Pb₂(AsO₄)₃","Pb₃(AsO₄)₂","PbAsO₄","Pb₃AsO₄"]'::jsonb, 'تطبيق', 'استنتاج الصيغة من تعبير Ksp', 'صعب', 'الكتاب ص 114 — س70'),
('mcq', 7, 'أيّ الأزواج الآتية (المركب، وتعبير ثابت حاصل ذائبيته) صحيح؟', null, null, '["PbI₂ : Ksp = [Pb²⁺][I⁻]","Al(OH)₃ : Ksp = [Al³⁺]³[OH⁻]","Ca₃(PO₄)₂ : Ksp = [Ca²⁺]²[PO₄³⁻]³","Ag₂CO₃ : Ksp = [Ag⁺]²[CO₃²⁻]"]'::jsonb, 'تطبيق', 'تمييز تعبير Ksp الصحيح', 'متوسط', 'الكتاب ص 101 — الجدول 3-3'),
('essay', 1, 'يمثل الشكل الآتي محلولًا مشبعًا من كرومات الفضة Ag₂CrO₄ فوق مادتها الصلبة.
(أ) اكتب معادلة اتزان الذوبان.
(ب) اكتب تعبير ثابت حاصل الذائبية.
(ج) فسّر عدم كتابة Ag₂CrO₄(s) في التعبير.', null, '[{"src":"qimg/chem22/c3-l3b-sat-ag2cro4.svg","alt":"كأس فيها محلول مشبع، وفي قاعها طبقة من مادة صلبة غير مذابة مكتوب عليها Ag₂CrO₄(s). في المحلول 8 أيونات Ag⁺ (دوائر رمادية) و4 أيونات CrO₄²⁻ (دوائر حمراء)، أي إن عدد أيونات Ag⁺ ضعف عدد أيونات CrO₄²⁻. وبجانب الكأس مفتاح يبين رمز كل أيون والمادة الصلبة غير المذابة."}]'::jsonb, null, 'تطبيق', 'كتابة معادلة وتعبير Ksp', 'سهل', 'الكتاب ص 100–101 — كتابة تعبير ثابت حاصل الذائبية'),
('essay', 2, 'اكتب معادلة اتزان الذوبان وتعبير ثابت حاصل الذائبية لكل من المركبات القليلة الذوبان الآتية:
