from (values
('mcq', 1, 'ثابت حاصل الذائبية لكربونات الكالسيوم CaCO₃ عند 298 K يساوي 3.4 × 10⁻⁹. ما تركيز أيونات Ca²⁺ في محلولها المشبع؟', null, null, '["1.7 × 10⁻⁹ mol/L","1.5 × 10⁻³ mol/L","5.8 × 10⁻⁵ mol/L","3.4 × 10⁻⁹ mol/L"]'::jsonb, 'تطبيق', 'حساب تركيز أيون من Ksp', 'سهل', 'الكتاب ص 102–103 — المثال 3-5 والمسألة 20'),
('mcq', 2, 'احسب تركيز أيون الهيدروكسيد [OH⁻] في محلول مشبع من Mg(OH)₂ عند 298 K، علمًا بأن Ksp = 5.6 × 10⁻¹².', null, null, '["2.2 × 10⁻⁴ mol/L","1.1 × 10⁻⁴ mol/L","2.4 × 10⁻⁶ mol/L","1.8 × 10⁻⁴ mol/L"]'::jsonb, 'تطبيق', 'حساب تركيز أيون من Ksp', 'متوسط', 'الكتاب ص 103 — المثال 3-6 حساب تركيز الأيون'),
('mcq', 3, 'يمثل الشكل الآتي محلولًا مشبعًا من فلوريد الكالسيوم CaF₂ عند 298 K، قيس فيه تركيز أيونات الكالسيوم. ما قيمة Ksp لـ CaF₂ المحسوبة من هذا القياس؟', null, '[{"src":"qimg/chem22/c3-l3b-sat-caf2.svg","alt":"كأس فيها محلول مشبع من فلوريد الكالسيوم، وفي قاعها طبقة من مادة صلبة غير مذابة مكتوب عليها CaF₂(s). في المحلول 3 أيونات Ca²⁺ (دوائر خضراء) و6 أيونات F⁻ (دوائر زرقاء). وبجانب الكأس مفتاح للرموز، وتحته مكتوب: [Ca²⁺] = 2.1 × 10⁻⁴ mol/L عند 298 K."}]'::jsonb, '["9.3 × 10⁻¹²","3.7 × 10⁻¹¹","1.9 × 10⁻¹¹","4.4 × 10⁻⁸"]'::jsonb, 'تطبيق', 'حساب Ksp من تركيز أيون', 'متوسط', 'الكتاب ص 103 — المسألة 22 (CaF₂)'),
('mcq', 4, 'ذائبية كلوريد الفضة AgCl في الماء عند 298 K تساوي 1.86 × 10⁻⁴ g في 100 g من الماء. إذا كانت الكتلة المولية لـ AgCl تساوي 143.32 g/mol، واعتُبر أن 100 g من الماء تشغل 100 mL وأن حجم المحلول لا يتغير، فما قيمة Ksp لـ AgCl؟', null, null, '["1.7 × 10⁻¹²","3.5 × 10⁻⁶","1.3 × 10⁻⁵","1.7 × 10⁻¹⁰"]'::jsonb, 'تطبيق', 'حساب Ksp من الذائبية', 'صعب', 'الكتاب ص 103 — المسألة 24'),
('mcq', 5, 'ثابت حاصل الذائبية لكرومات الفضة Ag₂CrO₄ عند 298 K يساوي 1.1 × 10⁻¹². ما تركيز أيونات Ag⁺ في محلولها المشبع؟', null, null, '["6.5 × 10⁻⁵ mol/L","1.3 × 10⁻⁴ mol/L","1.0 × 10⁻⁶ mol/L","1.6 × 10⁻⁴ mol/L"]'::jsonb, 'تطبيق', 'حساب تركيز أيون من Ksp', 'متوسط', 'الكتاب ص 103 — المسألة 22 (Ag₂CrO₄)'),
('mcq', 6, 'إذا كانت الذائبية المولارية لمركب أيوني صيغته AB₂ تساوي s، فأيّ العلاقات الآتية تربط Ksp بـ s؟', null, null, '["Ksp = s²","Ksp = 2s³","Ksp = 4s³","Ksp = 2s²"]'::jsonb, 'فهم', 'ربط Ksp بالذائبية', 'سهل', 'الكتاب ص 103 — المثال 3-6 حساب تركيز الأيون'),
('mcq', 7, 'يبين الجدول الآتي قيم Ksp لأربعة مركبات عند 298 K. أيّ هذه المركبات له أكبر ذائبية مولارية في الماء؟', '{"headers":["المركب","Ksp عند 298 K"],"rows":[["AgCl","1.8 × 10⁻¹⁰"],["Ag₂CrO₄","1.1 × 10⁻¹²"],["BaSO₄","1.1 × 10⁻¹⁰"],["AgBr","5.4 × 10⁻¹³"]]}'::jsonb, null, '["Ag₂CrO₄","AgCl","BaSO₄","AgBr"]'::jsonb, 'تحليل', 'مقارنة الذائبية من Ksp', 'صعب', 'الكتاب ص 101–103 — الجدول 3-3 واستعمال Ksp'),
('essay', 1, 'ثابت حاصل الذائبية ليوديد الرصاص PbI₂ عند 298 K يساوي 9.8 × 10⁻⁹. احسب الذائبية المولارية لـ PbI₂ وتركيز كل من أيونات Pb²⁺ وI⁻ في محلوله المشبع، مبينًا خطوات الحل.', null, null, null, 'تطبيق', 'حساب الذائبية وتراكيز الأيونات', 'متوسط', 'الكتاب ص 103 — المثال 3-6 حساب تركيز الأيون'),
('essay', 2, 'ذائبية فلوريد الباريوم BaF₂ في الماء عند 25°C تساوي 1.1 g/L، وكتلته المولية 175.33 g/mol. احسب الذائبية المولارية لـ BaF₂، ثم احسب تركيزي أيونيه وقيمة Ksp له.', null, null, null, 'تطبيق', 'حساب Ksp من الذائبية', 'صعب', 'الكتاب ص 114 — س77 (الجدول 3-6)'),
