('mcq', 1, 3, 'تتكون مينا الأسنان من 98% من هيدروكسي الأباتيت Ca₅(PO₄)₃OH، وهو مادة غير ذائبة في الماء (Ksp = 6.8 × 10⁻³⁷).', '["الفلوروأباتيت يتكون في المينا عند التعرض للفلوريد، وليس المكوّن الرئيس لها.","NaF مركب يُضاف إلى معجون الأسنان، وليس من مكونات المينا.","المينا مركب يحتوي على أيون الهيدروكسيد إلى جانب الكالسيوم والفوسفات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-06T22:20:31.262Z"}'::jsonb),
('mcq', 2, 1, 'Ca₅(PO₄)₃OH(s) ⇌ 5Ca²⁺(aq) + 3PO₄³⁻(aq) + OH⁻(aq). تحلل المينا ينتج عن ذوبان هيدروكسي الأباتيت خصوصًا عندما يحتوي اللعاب على أحماض؛ فالحمض يتفاعل مع OH⁻ فيقل تركيزه، فيُزاح الاتزان نحو اليمين (الذوبان) وفق مبدأ لوتشاتلييه.', '["أيونات الفلوريد تُكوّن الفلوروأباتيت الأقل ذائبية فتحمي المينا، لا تُسرّع ذوبانها.","","Ca²⁺ أيون مشترك مع هيدروكسي الأباتيت، فزيادة تركيزه تُزيح الاتزان نحو اليسار وتُقلل الذوبان ولا تُسرّعه.","الفلوروأباتيت أقل ذائبية من هيدروكسي الأباتيت، فوجوده يحمي المينا من الذوبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-06T22:20:31.262Z"}'::jsonb),
('mcq', 3, 2, 'للمركبين الصيغة العامة نفسها Ca₅(PO₄)₃X، فالمقارنة المباشرة لقيم Ksp تصح: 1 × 10⁻⁶⁰ أصغر بكثير من 6.8 × 10⁻³⁷، فالفلوروأباتيت أقل ذائبية، ولذلك يقل هدم المينا وإتلافها عند حلوله محل هيدروكسي الأباتيت.', '["Ksp للفلوروأباتيت (1 × 10⁻⁶⁰) أصغر بكثير، والمركبان متماثلان في نسب الأيونات، فهو الأقل ذائبية لا الأكبر.","Ksp للفلوروأباتيت أصغر لا أكبر، وقيمة Ksp لا تدل على سرعة الترسب.","","الفلوريد لا يغير Ksp لهيدروكسي الأباتيت؛ بل يحل محل OH⁻ مكونًا مركبًا جديدًا أقل ذائبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-06T22:20:31.263Z"}'::jsonb),
('mcq', 4, 0, 'Ca₅(PO₄)₃OH(s) + NaF(aq) → Ca₅(PO₄)₃F(s) + NaOH(aq)؛ يحل أيون الفلوريد محل أيون الهيدروكسيد فيتكون الفلوروأباتيت.', '["","أيونات الفوسفات تبقى في البناء Ca₅(PO₄)₃؛ الذي يُستبدل هو OH⁻ فقط.","الكالسيوم يبقى في المينا (Ca₅(PO₄)₃F)، وأيون Na⁺ يبقى في المحلول مع OH⁻.","هذا عكس ما يحدث؛ فالفلوروأباتيت يتكون حين يحل الفلوريد محل الهيدروكسيد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-06T22:20:31.263Z"}'::jsonb),
('mcq', 5, 1, 'Ca₅(PO₄)₃OH(s) ⇌ 5Ca²⁺(aq) + 3PO₄³⁻(aq) + OH⁻(aq)، فـ Ksp = [Ca²⁺]⁵[PO₄³⁻]³[OH⁻] = 6.8 × 10⁻³⁷.', '["أُهمل أيون OH⁻، وهو أحد الأيونات الناتجة عن ذوبان المركب.","","أُهملت المعاملات 5 و3 التي يجب أن تكون أسسًا للتركيزين.","المادة الصلبة لا تُكتب في تعبير Ksp."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-06T22:20:31.263Z"}'::jsonb),
('mcq', 6, 0, '2.7 × 10⁻⁵ ÷ 6.1 × 10⁻⁸ ≈ 4.4 × 10² أي نحو 440 مرة؛ فهيدروكسي الأباتيت أكبر ذائبية، والفلوروأباتيت الذي يتكون بوجود الفلوريد يذوب أقل بكثير فيحمي الأسنان من التسوس.', '["","قُلبت المقارنة؛ 6.1 × 10⁻⁸ أصغر من 2.7 × 10⁻⁵، فالفلوروأباتيت هو الأقل ذائبية.","نسبة الذائبيتين لا تساوي نسبة قيمتي Ksp؛ فالذائبية تُحسب بجذر من الدرجة التاسعة، والنسبة الصحيحة نحو 440.","تشابه الصيغة لا يعني تقارب الذائبية؛ فالقيمتان تختلفان بنحو 440 مرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-06T22:20:31.263Z"}'::jsonb),
('mcq', 7, 2, 'أغلب الناس يستعملون معجون أسنان يحتوي على فلوريد الصوديوم أو فلوريد القصدير II، وهما مصدر لأيونات F⁻ التي تحل محل OH⁻ في المينا.', '["هذان مركبان قليلا الذوبان، والمعجون يحتوي على مركبات فلوريد ذائبة توفر أيونات F⁻.","أيون الكلوريد لا يحل محل OH⁻ في المينا؛ الأيون الواقي هو الفلوريد.","","هذان مكوّنان للمينا نفسها، وليسا مضافين في معجون الأسنان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-06T22:20:31.263Z"}'::jsonb),
('essay', 1, null::int, null, null, 'مينا الأسنان مكوّنة أساسًا من هيدروكسي الأباتيت Ca₅(PO₄)₃OH، وهو قليل الذوبان (Ksp = 6.8 × 10⁻³⁷)، لكن ذوبانه يحدث ببطء خصوصًا حين يحتوي اللعاب على أحماض، فتتحلل المينا.
عند وجود أيونات الفلوريد (من معجون يحتوي على NaF أو SnF₂) يحدث تفاعل إحلال مزدوج يحل فيه F⁻ محل OH⁻:
Ca₅(PO₄)₃OH(s) + NaF(aq) → Ca₅(PO₄)₃F(s) + NaOH(aq)
الفلوروأباتيت الناتج (Ksp = 1 × 10⁻⁶⁰) أقل ذائبية بكثير من هيدروكسي الأباتيت، فيقل ذوبان المينا وهدمها، ولذلك تقل الإصابة بالتسوس.', '["المينا هيدروكسي الأباتيت ويذوب قليلًا (خاصة مع الأحماض)","معادلة الإحلال المزدوج","الفلوروأباتيت أقل ذائبية (مقارنة Ksp)","النتيجة: يقل هدم المينا"]'::jsonb, '[]'::jsonb, '[{"element":"وصف ذوبان هيدروكسي الأباتيت","marks":1},{"element":"معادلة الإحلال","marks":1},{"element":"مقارنة الذائبية","marks":1},{"element":"الربط بمنع التسوس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير مكتمل مع المعادلة ومقارنة الذائبية"},{"level":"2–3 درجات","description":"تفسير صحيح دون معادلة أو دون مقارنة الذائبية"},{"level":"1 درجة","description":"ذكر أن الفلوريد يقوي الأسنان دون تفسير كيميائي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الفلوروأباتيت أكثر ذائبية","القول إن الفلوريد يقتل البكتيريا فقط دون ربط بالذائبية","جعل F⁻ يحل محل PO₄³⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-06T22:20:31.263Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Ca₅(PO₄)₃OH(s) ⇌ 5Ca²⁺(aq) + 3PO₄³⁻(aq) + OH⁻(aq)؛ Ksp = [Ca²⁺]⁵[PO₄³⁻]³[OH⁻].
(ب) الفم نظام مفتوح؛ فاللعاب يتجدد ويُبتلع باستمرار فيحمل الأيونات الذائبة بعيدًا، فلا تتراكم تراكيزها حتى يصبح ناتج ضربها مساويًا لـ Ksp، فيستمر الذوبان. والأحماض تتفاعل مع أيونات OH⁻ (وأيونات الفوسفات) فتُنقص تراكيزها، فيُزاح الاتزان نحو الذوبان وفق مبدأ لوتشاتلييه.', '["معادلة الذوبان","تعبير Ksp","الفم نظام مفتوح تُزال فيه الأيونات","الأحماض تستهلك OH⁻ فيُزاح الاتزان نحو الذوبان"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة الذوبان","marks":1},{"element":"تعبير Ksp","marks":1},{"element":"تفسير غياب الاتزان","marks":1},{"element":"تفسير أثر الأحماض","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعادلة والتعبير صحيحان والتفسيران مكتملان"},{"level":"2–3 درجات","description":"المعادلة والتعبير صحيحان مع تفسير واحد، أو التفسيران مع خطأ في التعبير"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال OH⁻ في التعبير","القول إن الأحماض تزيد Ksp","عدم الإشارة إلى أن الأيونات تُزال باستمرار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-06T22:20:31.264Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) هيدروكسي الأباتيت: s⁹ = 6.8 × 10⁻³⁷ ÷ 84375 = 8.1 × 10⁻⁴²، ومنه s = 2.7 × 10⁻⁵ mol/L.
الفلوروأباتيت: s⁹ = 1 × 10⁻⁶⁰ ÷ 84375 = 1.2 × 10⁻⁶⁵، ومنه s = 6.1 × 10⁻⁸ mol/L.
(ب) 2.7 × 10⁻⁵ ÷ 6.1 × 10⁻⁸ ≈ 440؛ فذائبية هيدروكسي الأباتيت أكبر بنحو 440 مرة. لذلك عندما يحل الفلوريد محل الهيدروكسيد ويتكون الفلوروأباتيت تصبح المينا أقل ذوبانًا في اللعاب، فيقل هدمها وتسوسها.', '["s لهيدروكسي الأباتيت ≈ 2.7 × 10⁻⁵ mol/L","s للفلوروأباتيت ≈ 6.1 × 10⁻⁸ mol/L","النسبة نحو 440","الربط بالوقاية من التسوس"]'::jsonb, '["s⁹ = Ksp ÷ 84375","هيدروكسي الأباتيت: s = (6.8 × 10⁻³⁷ ÷ 84375)^(1/9) = 2.7 × 10⁻⁵ mol/L","الفلوروأباتيت: s = (1 × 10⁻⁶⁰ ÷ 84375)^(1/9) = 6.1 × 10⁻⁸ mol/L","النسبة = 2.7 × 10⁻⁵ ÷ 6.1 × 10⁻⁸ ≈ 4.4 × 10²"]'::jsonb, '[{"element":"ذائبية هيدروكسي الأباتيت","marks":2},{"element":"ذائبية الفلوروأباتيت","marks":1},{"element":"المقارنة والربط بالوقاية","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الحسابان صحيحان، والمقارنة والربط سليمان"},{"level":"3–4 درجات","description":"حساب واحد صحيح مع مقارنة سليمة، أو خطأ حسابي بسيط"},{"level":"1–2 درجة","description":"مقارنة نوعية صحيحة بقيم Ksp دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["أخذ الجذر التربيعي بدل التاسع","عدّ نسبة الذائبيتين مساوية لنسبة قيمتي Ksp","نسيان القسمة على 84375"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-06T22:20:31.264Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C3-L3-O10') and x.type = v.type and x.number = v.number
